export const PRODUCT_IMAGE_BUCKET = "product-images";
export const MAX_PRODUCT_IMAGE_SIZE = 5 * 1024 * 1024;
export const IMAGE_EXTENSIONS: Record<string, string> = { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp" };

/** Only paths generated by this application belong to the managed bucket. */
export function isProductImagePath(value: string): boolean {
  return /^products\/[a-zA-Z0-9_-]{1,100}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/.test(value);
}

export function resolveProductImage(image: string, baseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL): string {
  if (!isProductImagePath(image)) return image;
  if (!baseUrl) return "/placeholder.svg";
  return `${baseUrl.replace(/\/$/, "")}/storage/v1/object/public/${PRODUCT_IMAGE_BUCKET}/${image}`;
}

export function productImagePath(productId: string, uuid: string, mime: string): string {
  const path = `products/${productId}/${uuid}.${IMAGE_EXTENSIONS[mime]}`;
  if (!isProductImagePath(path)) throw new Error("invalid-image-path");
  return path;
}

export function validateProductImage(file: { size: number; type: string } | null, required = false): string | undefined {
  if (!file) return required ? "Escolha a imagem principal do produto." : undefined;
  if (!Object.hasOwn(IMAGE_EXTENSIONS, file.type)) return "Escolha uma imagem JPEG, PNG ou WebP.";
  if (file.size <= 0) return "A imagem está vazia. Escolha outro arquivo.";
  if (file.size > MAX_PRODUCT_IMAGE_SIZE) return "A imagem deve ter no máximo 5 MiB.";
}

/** Verify the file signature as well as the declared MIME on the server. */
export async function validateImageContent(file: Blob): Promise<string | undefined> {
  const bytes = new Uint8Array(await file.slice(0, 12).arrayBuffer());
  const starts = (signature: number[], offset = 0) => signature.every((byte, i) => bytes[offset + i] === byte);
  const valid = file.type === "image/jpeg" ? starts([0xff, 0xd8, 0xff])
    : file.type === "image/png" ? starts([137, 80, 78, 71, 13, 10, 26, 10])
    : file.type === "image/webp" && starts([82, 73, 70, 70]) && starts([87, 69, 66, 80], 8);
  if (!valid) return "O conteúdo do arquivo não corresponde a uma imagem JPEG, PNG ou WebP válida.";
}
